<script lang="ts">
 import '$lib/ui.css';
 import {onMount,tick} from 'svelte';import {page} from '$app/state';import {goto,invalidateAll} from '$app/navigation';
 import {clearDrafts,drafts,photos} from '$lib/offline';import {translator} from '$lib/app-i18n';import {authClient} from '$lib/auth-client';import Icon from '$lib/components/Icon.svelte';
 let {data,children}=$props();let t=$derived(translator(data.lang));let ready=$state(false),name=$state(''),mode=$state('standalone'),message=$state(''),busy=$state(false),query=$state(''),mac=$state(false);
 let searchDialog:HTMLDialogElement,navDialog:HTMLDialogElement,searchInput:HTMLInputElement;
 const groups=[{title:'uxPlanning',sections:['today','vineyard','harvest']},{title:'uxProduction',sections:['cellar','blends','lab','bottling','hygiene']},{title:'uxControl',sections:['costing','assistant','reports']},{title:'uxSystem',sections:['data','admin']}];
 let section=$derived(page.url.pathname.split('/')[2]??'today');
 const enabled=(s:string)=>['today','admin'].includes(s)||!data.settings?.modules?.length||data.settings.modules.includes(s);
 let results=$derived.by(()=>{const q=query.trim().toLocaleLowerCase();const items=groups.flatMap(g=>g.sections.filter(enabled).map(s=>({label:t(s),detail:t('uxIntro_'+s),href:'/app/'+s,icon:s})));const model=(page.data as any).model;
  if(q&&model){for(const [collection,route,param,icon] of [['lots','lab','lot','lab'],['vessels','cellar','vessel','cellar'],['vineyards','vineyard','vineyard','vineyard'],['tasks','today','task','today']])for(const row of model[collection]??[])items.push({label:row.title??[row.code,row.name].filter(Boolean).join(' · '),detail:t(icon),href:'/app/'+route+'?'+param+'='+encodeURIComponent(row.id),icon});}
  return items.filter(item=>!q||(item.label+' '+item.detail).toLocaleLowerCase().includes(q)).slice(0,20);
 });
 onMount(()=>{ready=true;mac=/Mac|iPhone|iPad/.test(navigator.platform);if(data.tenant)localStorage.setItem('vinea-active-winery',data.tenant.id);localStorage.setItem('vinea-language',data.lang);});
 async function create(){busy=true;message='';try{const res=await fetch('/api/tenants',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name,mode})});if(res.ok)await invalidateAll();else message=t((await res.json()).message??'CONNECTION_FAILED');}catch{message=t('CONNECTION_FAILED');}finally{busy=false;}}
 async function discardDeviceDrafts(){if(data.tenant&&((await drafts(data.tenant.id)).length+(await photos(data.tenant.id)).length)&&!confirm(t('discardConfirm')))return false;await clearDrafts();return true;}
 async function change(id:string){if(!await discardDeviceDrafts())return;try{const res=await fetch('/api/tenants',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({id})});if(!res.ok){message=t((await res.json()).message);return;}await invalidateAll();if(data.tenant)localStorage.setItem('vinea-active-winery',data.tenant.id);}catch{message=t('CONNECTION_FAILED');}}
 async function search(){searchDialog.showModal();await tick();searchInput.focus();}
 function keyboard(event:KeyboardEvent){if(event.key==='Escape'&&searchDialog?.open){event.preventDefault();searchDialog.close();query='';return;}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();if(!searchDialog.open)search();}}
</script>
<svelte:window onkeydown={keyboard}/>
<svelte:head><title>Vinea · {data.tenant?.name??t('winery')}</title></svelte:head>
<a href="#main" class="skip">{t('uxSkip')}</a>
{#snippet navigation()}
 <a class="brand" href="/app/today"><span class="brand-icon"><Icon name="vineyard" size={25}/></span><span>Vinea<small>WINERY WORKSPACE</small></span></a>
 {#if data.tenant}<label class="winery"><span>{t('winery')}</span><select value={data.tenant.id} onchange={(e)=>change(e.currentTarget.value)}>{#each data.tenants as tenant}<option value={tenant.id}>{tenant.name}</option>{/each}</select></label>{/if}
 <nav aria-label={t('navigation')}>{#each groups as group}<div class="nav-group"><p>{t(group.title)}</p>{#each group.sections.filter(enabled) as s}<a class:active={section===s} aria-current={section===s?'page':undefined} href={'/app/'+s} onclick={()=>navDialog?.close()}><Icon name={s} size={19}/><span>{t(s)}</span>{#if section===s}<span class="active-dot"></span>{/if}</a>{/each}</div>{/each}</nav>
 <div class="sidebarbottom"><div class="profile"><span class="avatar">{data.user.name.slice(0,2).toUpperCase()}</span><span><strong>{data.user.name}</strong><small>{data.tenant?t(data.tenant.role):''}</small></span></div><div class="languages" aria-label="Language">{#each ['de','en','it','fr'] as l}<a aria-current={l===data.lang?'true':undefined} class:selected={l===data.lang} href={'?lang='+l}>{l.toUpperCase()}</a>{/each}</div><button class="signout" onclick={async()=>{if(!await discardDeviceDrafts())return;await authClient.signOut();localStorage.removeItem('vinea-active-winery');await goto('/login');}}><Icon name="logout" size={16}/>{t('signout')}</button></div>
{/snippet}
<div class="shell"><aside class="sidebar">{@render navigation()}</aside><div class="workspace"><header class="topbar"><div class="breadcrumb"><button class="icon-button mobile" disabled={!ready} onclick={()=>navDialog.showModal()} aria-label={t('navigation')}><Icon name="menu"/></button><span class="breadcrumb-winery">{data.tenant?.name??'Vinea'}</span><span class="separator">/</span><strong>{t(section)}</strong></div><div class="header-tools"><button class="quick-search secondary" aria-label={t('uxSearchTitle')} disabled={!ready} onclick={search}><Icon name="search" size={18}/><span>{t('uxSearchTitle')}</span><kbd>{mac?'⌘':'Ctrl'} K</kbd></button><a class="header-avatar" href="/app/admin" aria-label={t('admin')}>{data.user.name.slice(0,2).toUpperCase()}</a></div></header><main id="main" tabindex="-1" inert={!ready}>{#if message}<p class="notice" role="alert">{message}</p>{/if}{#if !data.tenant}<section class="card onboarding"><span class="pill good">VINEA</span><h1>{t('createWinery')}</h1><form onsubmit={(e)=>{e.preventDefault();create();}}><label>{t('name')}<input bind:value={name} required minlength="2" maxlength="120" /></label><label>{t('mode')}<select bind:value={mode}>{#each ['standalone','erp','companion'] as m}<option value={m}>{t(m)}</option>{/each}</select></label><button disabled={!ready||busy}>{busy?t('saving'):t('createWinery')}</button></form></section>{:else}{@render children()}{/if}</main><footer>Vinea <span>·</span> {data.tenant?.name??t('winery')}</footer></div></div>
<dialog class="mobile-nav" bind:this={navDialog} aria-label={t('navigation')}><div class="nav-close"><button class="icon-button" onclick={()=>navDialog.close()} aria-label={t('uxClose')}><Icon name="close"/></button></div>{@render navigation()}</dialog>
<dialog class="search-dialog" bind:this={searchDialog} aria-label={t('uxSearchTitle')}><div class="dialog-header"><h2>{t('uxSearchTitle')}</h2><button class="icon-button" onclick={()=>searchDialog.close()} aria-label={t('uxClose')}><Icon name="close"/></button></div><label><span class="sr-only">{t('search')}</span><input type="search" bind:this={searchInput} bind:value={query} placeholder={t('uxSearch')}/></label><div class="search-results">{#each results as result}<a href={result.href} onclick={()=>searchDialog.close()}><Icon name={result.icon}/><span><strong>{result.label}</strong><small>{result.detail}</small></span><Icon name="arrow" size={17}/></a>{:else}<p class="empty-state">{t('uxSearchEmpty')}</p>{/each}</div></dialog>
<style>
 .shell{min-height:100vh}.sidebar{position:fixed;inset:0 auto 0 0;width:256px;z-index:20;background:#fff;border-right:1px solid var(--line);padding:26px 18px 16px;display:flex;flex-direction:column;overflow:auto}.brand{display:flex;gap:11px;align-items:center;text-decoration:none;color:#164b37;font-size:26px;letter-spacing:-.7px;font-weight:750;margin:0 8px 27px}.brand-icon{display:grid;place-items:center;width:42px;height:44px;background:var(--tint);border-radius:12px}.brand small{display:block;font-size:8px;letter-spacing:1.2px;line-height:1.5;color:var(--muted);font-weight:600}.winery{padding:0 7px;margin-bottom:14px;font-size:11px}.winery select{font-size:12px;font-weight:550;background:#f8faf9}nav{display:grid;gap:12px}.nav-group p{margin:10px 12px 6px;color:#576f62;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:1px}.nav-group a{display:flex;align-items:center;gap:12px;min-height:42px;padding:10px 12px;border-radius:8px;text-decoration:none;color:#486258;font-size:13px;font-weight:500}.nav-group a:hover{background:#f3f7f4}.nav-group a.active{background:#e9f5ee;color:#176146;font-weight:650}.active-dot{margin-left:auto;width:6px;height:6px;border-radius:50%;background:var(--brand)}.sidebarbottom{margin-top:auto;padding:24px 8px 0}.profile{display:flex;align-items:center;gap:10px}.profile strong{display:block;font-size:12px}.profile small{display:block;color:var(--muted);font-size:11px}.avatar,.header-avatar{display:grid;place-items:center;width:36px;height:36px;background:#e8f0eb;color:#315c47;font-size:11px;font-weight:700;border-radius:11px;text-decoration:none}.languages{display:flex;gap:4px;margin-top:18px}.languages a{padding:6px 9px;border-radius:6px;font-size:10px;font-weight:650;text-decoration:none;color:var(--muted)}.languages a.selected{background:var(--tint);color:var(--brand)}.signout{background:transparent;color:var(--muted);padding:8px 2px;font-size:11px;display:flex;align-items:center;gap:10px}.workspace{margin-left:256px}.topbar{height:76px;display:flex;align-items:center;justify-content:space-between;gap:20px;padding:0 32px;background:#ffffffee;border-bottom:1px solid var(--line);position:sticky;top:0;z-index:15;backdrop-filter:blur(12px)}.breadcrumb{display:flex;gap:15px;align-items:center;font-size:12px;min-width:0}.breadcrumb-winery{color:var(--muted);max-width:260px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.separator{color:#a1b1a7}.header-tools{display:flex;align-items:center;gap:16px}.quick-search{display:flex;align-items:center;gap:10px;min-height:38px;font-size:12px;font-weight:500;padding:8px 12px;color:var(--muted)}kbd{padding:1px 5px;background:#f3f6f4;border:1px solid var(--line);border-radius:4px;font-size:10px;margin-left:18px}main{padding:30px 32px 40px;max-width:1640px;margin:0 auto;min-width:0}footer{display:flex;justify-content:center;gap:10px;padding:10px 0 24px;color:var(--muted);font-size:11px}.onboarding{max-width:520px;margin:6vh auto}.onboarding form{display:grid;gap:20px}.skip{position:fixed;left:20px;top:-70px;padding:12px;background:white;z-index:100}.skip:focus{top:15px}.mobile{display:none}.mobile-nav{margin:0 auto 0 0;max-height:100dvh;height:100dvh;max-width:290px;border-radius:0;padding:24px 18px}.nav-close{display:flex;justify-content:flex-end;margin-bottom:8px}.search-dialog{max-width:660px}.search-results{display:grid;gap:4px;margin-top:14px;max-height:55vh;overflow:auto}.search-results a{display:flex;align-items:center;gap:14px;padding:12px;border-radius:9px;color:var(--ink);text-decoration:none}.search-results a:hover{background:var(--tint)}.search-results a>span{flex:1;min-width:0}.search-results strong{font-size:13px;display:block}.search-results small{font-size:11px;color:var(--muted);display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}@media(min-width:1500px){main{padding:36px 44px}}@media(max-width:1050px){.sidebar{width:226px}.workspace{margin-left:226px}.topbar{padding:0 24px}main{padding:26px 24px}}@media(max-width:800px){.sidebar{display:none}.workspace{margin-left:0}.mobile{display:inline-flex}.topbar{height:66px;padding:0 16px}.breadcrumb-winery,.separator{display:none}.quick-search span,.quick-search kbd{display:none}.quick-search{width:40px;justify-content:center;padding:9px}.header-tools{gap:10px}main{padding:22px 16px}.header-avatar{width:32px;height:32px}}
</style>
